/* Stateful clickable prototype. No banking services or real money operations. */
(() => {
  'use strict';
  const M=window.EnvelopeGame, main=document.querySelector('main');
  const BRAND='Альфа конверты';
  const KEY='envelopes-prototype:v2', UIKEY=KEY+':ui';
  const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
  const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(n||0)+' ₽';
  const date=key=>key?new Date(key+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'UTC'}):'—';
  const month=key=>new Date(key+'-01T12:00:00Z').toLocaleDateString('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'});
  const button=(label,action,attrs='',cls='btn-secondary')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${e(label)}</button>`;
  const link=(label,view,attrs='',cls='btn-secondary')=>`<a class="btn ${cls}" href="#${view}" data-view="${view}" ${attrs}>${e(label)}</a>`;
  const row=(label,value)=>`<div class="data-row"><span>${e(label)}</span><strong>${e(value)}</strong></div>`;
  const note=text=>`<p class="prototype-note">${e(text)}</p>`;
  const card=(title,body)=>`<section class="content-card"><h2>${e(title)}</h2>${body}</section>`;
  const field=(label,name,value='',type='text',attrs='')=>`<label class="form-field"><span>${e(label)}</span><input name="${name}" data-input="${name}" type="${type}" value="${e(value)}" ${type==='number'?(attrs.includes('min=')?'':'min="0" ')+ 'step="0.01" inputmode="decimal"':''} ${attrs}></label>`;
  const select=(label,name,items,value,attrs='')=>`<label class="form-field"><span>${e(label)}</span><select name="${name}" ${attrs}>${items.map(item=>`<option value="${e(item.id)}" ${item.id===value?'selected':''}>${e(item.name)}</option>`).join('')}</select></label>`;
  const submit=label=>`<button class="btn btn-primary" type="submit">${e(label)}</button>`;
  const form=(kind,body,attrs='')=>`<form data-form="${kind}" class="prototype-form" ${attrs}>${body}<p class="form-message" role="alert" hidden></p></form>`;
  const actions=body=>`<div class="button-row prototype-actions">${body}</div>`;
  const rewardLink=()=>link('Условия наград','reward-terms','','btn-quiet');
  let s,ctx={envelope:'cafe',source:'free',amount:3200};
  try{s=M.restore(JSON.parse(sessionStorage.getItem(KEY)));ctx={...ctx,...JSON.parse(sessionStorage.getItem(UIKEY)||'{}')};}catch{}
  let view=location.hash.slice(1)||'bank';
  if(!s)s=M.create('A');
  if(view==='table')prepareTable();
  let toastTimer;
  function save(){try{sessionStorage.setItem(KEY,JSON.stringify(s));sessionStorage.setItem(UIKEY,JSON.stringify(ctx));}catch{}}
  function announce(text){const el=$('.toast');el.textContent=text;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4200);}
  function go(next,options={},replace=false){view=next;ctx={...ctx,...options};history[replace?'replaceState':'pushState']({view,ctx},'', '#'+view);save();render();window.scrollTo(0,0);}
  function mutate(fn,next,options={}){try{fn();save();if(next)go(next,options);else render();}catch(error){showError(error.message);}}
  function showError(text){let el=$('main .form-message');if(!el){el=document.createElement('p');el.className='form-message';el.setAttribute('role','alert');main.prepend(el);}el.textContent=text;el.hidden=false;el.scrollIntoView({block:'center'});}
  function g(){return M.goal(s);}
  function envelopeName(id){return M.totals(s).find(x=>x.id===id)?.name||'Вне плана';}
  function options(){return M.totals(s).map(x=>({id:x.id,name:x.name}));}

  const iconPaths={
    envelope:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',
    coffee:'<path d="M4 8h12v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5V8Z"/><path d="M16 9h2a3 3 0 0 1 0 6h-2M7 3v2m5-2v2M3 22h15"/>',
    bag:'<path d="M5 7h14l1 14H4L5 7Zm3 0V5a4 4 0 0 1 8 0v2"/>',
    car:'<path d="m4 10 2-6h12l2 6M3 10h18v9H3ZM6 19v2m12-2v2M6 14h2m8 0h2"/>',
    home:'<path d="m3 11 9-8 9 8v10h-7v-7h-4v7H3Z"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
    target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
    sparkle:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z"/>',
    refund:'<path d="M9 5 4 10l5 5M4 10h10a6 6 0 1 1 0 12"/>',
    card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 9h20M6 15h4"/>',
    arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'
  };
  const uiIcon=name=>`<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.envelope}</svg>`;
  function bankStub(label){const d=$('#demo-message');$('#message-title').textContent=label;$('[data-message-content]').textContent='Раздел пока недоступен в прототипе. Откройте «Игровой стол», чтобы попробовать «'+BRAND+'».';d.showModal();}

  function seedPurchases(){[['Кофейня',380,'restaurant'],['Супермаркет',1280,'supermarket'],['Такси',240,'taxi']].forEach(([name,amount,category])=>{if(M.cardBalance(s)>=amount)M.createPurchase(s,{name,amount,category});});}
  function prepareTable(){if(!s.onboarded&&s.mode==='A'){M.setForecast(s,120000,Object.fromEntries(M.baseEnvelopes.map(x=>[x.id,x.plan])));const receipt=s.receipts.find(r=>!r.allocated&&r.month===s.month);if(receipt)M.distribute(s,receipt.id,M.suggestDistribution(s,receipt));if(!s.operations.length)seedPurchases();}}
  function nav(){return `<nav class="tabs" aria-label="Разделы конвертов">${['table','tasks','goal','summary'].map((v,i)=>link(['Мой стол','Задания','Цель','Итоги'][i],v,'',v===view?'btn-dark':'btn-secondary')).join('')}</nav>`;}
  function terms(){return `<div class="deposit-terms">${row('Ставка для расчёта','До 9% годовых · демонстрационный пример')}${row('Срок',month(g().deadline)+' · по сроку вашей цели')}${row('Пополнение','Доступно')}${row('Досрочное снятие','В примере проценты к выплате пересчитываются до 0 ₽')}${note('Ставка, порядок пересчёта процентов и ограничения — заглушки для согласования с продуктом и комплаенсом. Это условия демонстрации, а не предложение банка.')}</div>`;}
  function taskCard(compact=false){const t=M.task(s),first=!t.analytical,title=first?(t.kind==='payroll'?'Перенесите зарплату на карту':'Сделайте первую обычную покупку картой'):t.kind==='pinch'?`Отщипните ${money(t.target)} в цель`:'На 10% меньше на фастфуд';
    const reason=first?'Пока идут обучающие шаги. Демонстрационный порог аналитики: 3 покупки и первый итог; финальный порог согласуется. Специально покупать ничего не нужно.':t.kind==='pinch'?'В ваших конвертах появилась возможность отложить часть денег на цель.':`В прошлом месяце на фастфуд ушло ${money(t.reference)}. Ориентир на этот месяц — ${money(t.target)}.`;
    const stateLabel={offered:'Предложение от банка',accepted:'Вы приняли задание',deferred:'Отложено — без последствий',completed:'Выполнено'}[M.taskComplete(s)?'completed':t.status]||'Предложение от банка';
    const progress=first?(t.kind==='payroll'?(s.payrollTransferred?'Зарплата перенесена':'Передайте реквизиты работодателю'):(s.operations.some(o=>o.amount>0)?'Первая покупка появилась':'Ожидаем первую покупку')):t.kind==='pinch'?`${money(t.progress)} из ${money(t.target)}`:`Потрачено ${money(t.progress)} · ориентир ${money(t.target)}. ${t.progress>t.target?'Можно спокойно пересмотреть план.':`До ориентира ${money(t.target-t.progress)}.`}`;
    return `<article class="task-card"><span class="eyebrow">${e(stateLabel)}</span><h3>${e(title)}</h3><p>${e(reason)}</p><p>${e(progress)}</p>${!first?row('Срок','До '+date(new Date(Date.UTC(Number(s.month.slice(0,4)),Number(s.month.slice(5)),0)).toISOString().slice(0,10))):''}<div class="progress"><span style="--progress:${Math.min(100,t.progress/t.target*100)}%"></span></div>${note('Награда: бонусы или участие в акции · размер и условия — заглушки. Медицина, аптеки, ЖКУ, образование и дети не используются в заданиях на сокращение расходов.')}${rewardLink()}${compact?actions(button('Беру','task-accept')+button('Позже','task-defer')+button('Заменить','task-replace')+link('Подробнее','tasks','','btn-quiet')):actions(button('Беру','task-accept')+button('Позже','task-defer')+button('Заменить','task-replace')+(first?link('Перенести зарплату','payroll'):t.kind==='pinch'&&M.canPinch(s)?link('Перейти к щипку','pinch',`data-source="card" data-amount="${t.target}"`):link('К связанному конверту','envelope',`data-id="${e(s.bindings.fastfood||'cafe')}"`)))}</article>`;
  }
  function boardData(){if(view==='trial'||view==='training'){const kind=view,all=M.trialOperations.slice(0,kind==='training'?3:10),assigned=s[kind].assignments;return {kind,operations:all.filter(o=>!assigned[o.id]),all,envelopes:M.baseEnvelopes.map(x=>({...x,spent:all.filter(o=>assigned[o.id]===x.id).reduce((a,o)=>a+o.amount,0)}))};}
    if(view!=='table')return null;return {kind:'table',operations:M.pending(s).map(o=>({...o,suggested:o.suggested||M.suggested(s,o)})),all:M.currentOps(s),envelopes:M.totals(s)};}
  function operationCard(o,practice=false){return `<div class="operation-slot"><button type="button" class="figma-operation interactive-operation" data-operation="${e(o.id)}" aria-pressed="false" aria-describedby="board-instructions" draggable="false"><span class="operation-grip" aria-hidden="true">⠿</span><span class="operation-category" aria-hidden="true">${uiIcon(o.amount<0?'refund':o.category==='taxi'?'car':o.category==='supermarket'?'bag':o.category==='utilities'?'home':['medicine','education','children'].includes(o.category)?'shield':'coffee')}</span><span class="operation-amount">${e(money(o.amount))}</span><span class="operation-name">${e(o.name)}</span><span class="operation-time">${e(o.time)}</span><span class="operation-type">${e(M.categories.find(c=>c.id===o.category)?.name||'Покупка')}</span><span class="operation-suggestion">→ ${e(envelopeName(o.suggested))}</span><span class="operation-hold">${practice?'Пример · ':''}Удерживайте и переносите</span></button>${practice?'':button('Всегда сюда','rule-edit',`data-id="${e(o.id)}"`,'btn-quiet operation-rule')}</div>`;}
  function renderBoard(practice=false){const d=boardData(),pending=d.operations;
    const envelopes=d.envelopes.map(x=>`${practice?'':`<div class="envelope-slot ${x.id==='unplanned'?'envelope-outside':''}">`}<button type="button" class="figma-envelope envelope-drop-target ${practice?'practice-envelope':''}" data-drop-envelope="${e(x.id)}" data-tone="${({groceries:'sage',bills:'blue',transport:'sand',cafe:'rose',reserve:'lavender',free:'paper',unplanned:'outside'})[x.id]||'sand'}" ${practice?'':`data-view="envelope" data-id="${e(x.id)}"`}><span class="envelope-symbol" aria-hidden="true">${uiIcon(({groceries:'bag',bills:'home',transport:'car',cafe:'coffee',reserve:'shield',free:'grid',unplanned:'sparkle'})[x.id]||'envelope')}</span><span class="envelope-name">${e(x.name)}</span><strong class="envelope-balance">${e(money(practice?x.spent:x.id==='unplanned'?x.spent:x.remaining))}</strong><span>${practice?'Покупки примера':x.id==='unplanned'?'Траты вне прогноза':x.id==='free'?'Доступно без распределения':'Осталось в конверте'}</span>${practice?'':`<span class="envelope-spent">Потрачено <span class="money-value">${e(money(x.spent))}</span></span><span class="envelope-plan"><span class="allocation-row">Прогноз <span class="money-value">${e(money(x.plan))}</span></span><span class="allocation-row">Выделено <span class="money-value">${e(money(x.funded))}</span></span></span>${taskProgressFor(x.id)}`}</button>${practice?'':`${M.canPinch(s)&&M.available(s,x.id)>0&&!['reserve','unplanned'].includes(x.id)?link(`Отщипнуть ${money(M.available(s,x.id))}`,'pinch',`data-source="${x.id}" data-amount="${M.available(s,x.id)}"`,'btn-quiet envelope-pinch'):''}</div>`}`).join('');
    const isDone=practice?!pending.length:M.currentOps(s).length>0&&!pending.length;
    const hand=`<section class="content-card interactive-hand" id="purchase-hand" tabindex="-1" aria-label="${practice?'Учебные карточки покупок':'Карточки покупок'}"><div class="hand-heading"><h2>${isDone?(practice?'Партия разобрана':'День разобран'):pending.length?`Ваша рука · ${pending.length}`:'Рука пуста'}</h2><span class="badge">${practice?'Пример · баланс не меняется':isDone?'✓ Все покупки разложены':`${money(pending.reduce((n,o)=>n+o.amount,0))} к разбору`}</span></div><p class="hand-instructions" id="board-instructions">${practice?'Это примеры.':'Покупки уже оплачены.'} Зажмите карточку и перенесите в конверт. Можно выбрать карточку нажатием, затем нажать конверт.</p>${pending.length?`<div class="card-hand">${pending.map(o=>operationCard(o,practice)).join('')}</div>`:note(isDone?'Все операции учтены. Можно заниматься своими делами.':'После обычной покупки картой появится новая карточка и уведомление. Специально покупать ничего не нужно.')}${actions((pending.length?button('Разложить по подсказкам','sort-all','','btn-primary'):practice?link('Продолжить',view==='trial'?'trial-result':'setup','','btn-primary'):isDone?link('Награда за день','rewards')+link('Итог месяца','summary'):link('Перенести зарплату','payroll'))+(s.assignmentHistory?.length&&!practice&&!s.monthClosed?button('Отменить последнее','undo'):'')+(practice?button('Попробовать заново','practice-reset'):'')+(view==='training'?link('Пропустить обучение','setup'):'') )}${rewardLink()}</section>`;
    if(practice)return `<section class="game-table-surface"><div class="board-caption"><span class="eyebrow">Учебный стол</span><span>Без списаний · ${pending.length} карточек в руке</span></div><div class="envelope-board">${envelopes}</div>${hand}</section>`;
    const total=s.goals.reduce((n,g)=>n+g.balance,0),percent=Math.min(100,g().balance/g().target*100);
    return `${monthJourney()}<div class="game-stats"><div><span>На карте</span><strong>${e(money(M.cardBalance(s)))}</strong><small>Деньги доступны для покупок</small></div><div><span>Потрачено за месяц</span><strong>${e(money(M.currentOps(s).reduce((n,o)=>n+o.amount,0)))}</strong><small>${e(month(s.month))}</small></div><div><span>Уже в целях</span><strong>${e(money(total))}</strong><small>Шаг за шагом к важному</small></div></div>${s.monthClosed?note('Месяц закрыт. Операции доступны для просмотра; щипок по итогу можно подтвердить отдельно.'):''}
    <div class="game-layout"><section class="game-table-surface"><div class="board-caption"><div><span class="eyebrow">Ваш бюджет — ваш ход</span><h2>Всё по конвертам</h2></div><span class="board-status">${pending.length?'К разбору: '+pending.length:'Порядок на столе'}</span></div><div class="envelope-board">${envelopes}</div>${hand}</section>
    <aside class="round-panel" aria-label="Цель и задание"><section class="round-goal"><div class="goal-emblem">${uiIcon('target')}</div><span class="eyebrow">Ради большой мечты</span><h2>${e(g().name)}</h2><strong class="goal-total">${e(money(g().balance))}</strong><p>из ${e(money(g().target))}</p><div class="progress" role="progressbar" aria-label="Прогресс цели" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><span style="--progress:${percent}%"></span></div>${row('Плановый щипок',money(g().monthly))}${row('Ждёт подтверждения',money(M.goalReserve(s)))}${milestoneHint()}${actions(link('Посмотреть цель','goal')+(M.canPinch(s)&&M.cardBalance(s)>0?link('Отщипнуть в цель','pinch',`data-source="${M.goalReserve(s)>0?'planned':'card'}" data-amount="${Math.min(3200,M.available(s,M.goalReserve(s)>0?'planned':'card'))}"`,'btn-primary'):''))}</section>${taskCard(true)}</aside></div>${actions(link('Настроить конверты','settings')+link('Прогноз месяца','forecast'))}${demoEvents()}`;

  }
  function demoEvents(){if(s.monthClosed)return card('Продолжим в следующем месяце',note('Текущий итог сохранён. Новые покупки, поступления и возвраты можно показать после перехода к следующему месяцу.')+link('Начать следующий месяц','next'));return `<details class="demo-events" open><summary>Попробовать события месяца</summary><p>Добавьте пример покупки или поступления, чтобы пройти игровой цикл. Все суммы учебные.</p>${actions(link('Добавить покупку','purchase')+link('Показать аванс или зарплату','income')+button('Следующий день','next-day')+button('Три покупки для примера','seed'))}</details>`;}
  function monthJourney(){
    const pending=M.pending(s),receipt=s.receipts.find(r=>r.month===s.month&&!r.allocated),allocated=s.receipts.some(r=>r.month===s.month&&r.allocated),sorted=M.currentOps(s).length>0&&!pending.length;
    const steps=[['Прогноз','forecast',s.onboarded],['Раздача','salary',allocated],['Покупки','history',sorted],['Щипок','goal',M.currentTransfers(s).length>0],['Итог','summary',s.monthClosed],['Новый месяц','next',false]];
    let title,description,action;
    if(s.mode==='B'&&!s.hasCard){title='Начните с карты и учебной партии';description='Попробуйте переносить примеры, прежде чем появится первая покупка.';action=link('К началу','new','','btn-primary');}
    else if(!s.onboarded){title='Задайте свой прогноз';description='Пять конвертов уже готовы. Укажите доход и суммы расходов на месяц.';action=link('Настроить прогноз','forecast','','btn-primary');}
    else if(s.monthClosed){title='Итог сохранён — можно начать новый месяц';description='Прогноз уже подготовлен по вашим расходам. Накопления и правила сохранятся.';action=link('Прогноз следующего месяца','next','','btn-primary');}
    else if(receipt){title='Поступление ждёт раздачи: '+money(receipt.amount);description='Распределите деньги по прогнозу. Они останутся на карте.';action=link('Распределить поступление','salary',`data-receipt="${e(receipt.id)}"`,'btn-primary');}
    else if(s.mode==='B'&&!s.payrollTransferred&&!s.receipts.length){title='Пока рука пуста — перенесите зарплату';description='Передайте реквизиты работодателю, затем дождитесь первой обычной покупки.';action=link('Перенести зарплату','payroll','','btn-primary');}
    else if(pending.length){title='Ваш ход: карточек к разбору — '+pending.length;description='Зажмите покупку и перенесите в конверт. Можно разложить всё по подсказкам.';action=button('К карточкам','focus-hand','','btn-primary');}
    else if(!sorted){title='Рука пуста. Следующая покупка появится здесь';description='В прототипе можно добавить пример операции. Специально покупать ничего не нужно.';action=link('Попробовать покупку','purchase','','btn-primary');}
    else{title='День разобран';description='Награда за усердие доступна. Посмотрите остатки или подведите итог месяца.';action=link('Посмотреть итог месяца','summary','','btn-primary');}
    return `<section class="month-journey" aria-label="Ход месяца"><div class="journey-heading"><h2>Ход месяца</h2><span>Щипок — по вашему желанию</span></div><ol class="journey-steps">${steps.map(([name,target,done],i)=>`<li class="${done?'is-done':''}">${target==='next'&&!s.monthClosed?`<span class="journey-link"><b>${i+1}</b><span>${name}</span></span>`:link(name,target,`aria-label="${e(name)}${done?' — готово':''}"`,'journey-link').replace('>'+name+'</a>',`><b aria-hidden="true">${done?'✓':i+1}</b><span>${name}</span></a>`)}</li>`).join('')}</ol><div class="journey-next"><div><h3>${e(title)}</h3><p>${e(description)}</p></div>${action}</div>${actions(link('Все операции','history',`data-period="${e(s.month)}"`)+link('Правила магазинов','rules')+link('Регулярный щипок','regular')+link('Мои награды','rewards'))}</section>`;
  }
  function taskProgressFor(envelope){const t=M.task(s);if(!t.analytical||t.kind!=='fastfood'||s.bindings.fastfood!==envelope)return '';return `<span class="envelope-task">Задание: ${e(money(t.progress))} из ${e(money(t.target))}</span>`;}
  function milestoneHint(){const reached=[25,50,75,100].filter(p=>g().balance>=g().target*p/100).pop();return reached?`<div class="goal-milestone"><strong>Этап ${reached}% достигнут</strong><p>Место для предложения партнёра · условия появятся после согласования.</p>${link('Посмотреть этапы','milestones','','btn-quiet')}</div>`:'';}
  function forecastFields(plans=s.envelopes.reduce((a,x)=>(a[x.id]=x.plan,a),{})){return s.envelopes.map(x=>field(x.name,x.id,plans[x.id]??'','number','required')).join('');}
  function operationEnvelopeName(o){if(!o.envelope)return 'В руке';const archive=s.archives.find(a=>a.month===o.month);return archive?.rows.find(x=>x.id===o.envelope)?.name||envelopeName(o.envelope);}
  function transactionList(operations){return operations.length?`<div class="transaction-list">${operations.map(o=>`<article class="transaction-row"><div><strong>${e(o.name)}</strong><p>${e(month(o.month))} · ${e(o.time)} · <span class="money-value">${e(money(o.amount))}</span></p><p>${e(operationEnvelopeName(o))}${o.refundOf?' · возврат покупки':''}</p></div>${actions((o.month===s.month&&!s.monthClosed?link(o.envelope?'Переложить':'Выбрать конверт','move',`data-id="${e(o.id)}"`):'')+(!s.monthClosed&&M.refundable(s,o)>0?link('Возврат','refund',`data-id="${e(o.id)}"`):'')+(o.amount>0?button('Всегда сюда','rule-edit',`data-id="${e(o.id)}"`):''))}${o.month!==s.month||s.monthClosed?note('Раскладка закрытого месяца сохранена. Возврат учитывается в текущем месяце.'):''}</article>`).join('')}</div>`:note('Покупок по этим условиям пока нет.');}
  function historyPage(){
    const selectedMonth=ctx.historyMonth||s.month,selectedEnvelope=ctx.historyEnvelope||'all',query=ctx.historyQuery||'';
    const months=[...new Set([s.month,...s.operations.map(o=>o.month)])].sort().reverse().map(id=>({id,name:month(id)}));
    const archived=s.archives.find(a=>a.month===selectedMonth),envelopes=archived?archived.rows:M.totals(s).filter(x=>!['free','unplanned'].includes(x.id));
    const targets=[{id:'all',name:'Все конверты'},{id:'pending',name:'В руке'},...envelopes.map(x=>({id:x.id,name:x.name})),{id:'free',name:'Свободные'},{id:'unplanned',name:'Вне плана'}];
    const operations=s.operations.filter(o=>o.month===selectedMonth&&(selectedEnvelope==='all'||(selectedEnvelope==='pending'?!o.envelope:o.envelope===selectedEnvelope))&&o.name.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru'))).slice().reverse();
    return card('Все операции',note('Покупка списана с карты один раз. Здесь можно уточнить конверт или показать возврат. Закрытые итоги сохраняются.')+form('history-filters',`<div class="form-grid">${select('Месяц','period',months,selectedMonth)}${select('Конверт','envelope',targets,selectedEnvelope)}${field('Найти магазин','query',query,'search','maxlength="80"')}</div>`+submit('Показать операции'))+row('Найдено операций',String(operations.length))+row('Расход с учётом возвратов',money(operations.reduce((n,o)=>n+o.amount,0)))+transactionList(operations)+actions(link(selectedMonth===s.month?'Итог месяца':'Сохранённый итог',selectedMonth===s.month?'summary':'archive',`data-month="${e(selectedMonth)}"`)+link('К столу','table')));
  }
  function archivePage(){const r=s.archives.find(a=>a.month===ctx.archiveMonth);if(!r)return card('Сохранённый итог',note('После завершения месяца здесь появится его итог.')+link('К текущему месяцу','summary'));return card('Итог · '+month(r.month),note('Это сохранённый итог. Возвраты прошлых покупок учитываются отдельными карточками текущего месяца.')+`<div class="report-table-wrap"><table class="report-table"><thead><tr><th>Конверт</th><th>Исходный</th><th>Прогноз</th><th>Факт</th><th>Результат</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${e(x.name)}</td><td>${money(x.original)}</td><td>${money(x.plan)}</td><td>${money(x.actual)}</td><td>${x.matched?'Сошлось':'Разница '+money(Math.abs(x.difference))}</td></tr>`).join('')}</tbody></table></div>`+row('За месяц',r.matched?'Сошлось в пределах демонстрационного допуска':'Есть разница с прогнозом')+row('Прогноз / факт',money(r.planned)+' / '+money(r.actual))+row('Вне плана',money(r.unplanned))+row('Свободные: покупки',money(r.freeSpent))+row('Всего расходов',money(r.actual))+row('Экономия без Запаса',money(r.savings))+row('Отщипнуто во вклад',money(r.pinched))+actions(link('Покупки этого месяца','history',`data-period="${e(r.month)}"`)+link('Текущий месяц','summary')));}
  function notificationsPage(){return card('Уведомления',s.notifications.length?s.notifications.map(n=>{
    let action='';
    if(n.type==='salary'){const receipt=s.receipts.find(r=>r.id===n.payload.receiptId);action=receipt?.month===s.month&&!receipt.allocated&&!s.monthClosed?link('Распределить поступление','salary',`data-receipt="${e(receipt.id)}"`):note(receipt?.allocated?'Поступление уже распределено.':'Поступление сохранено в истории.');}
    else if(n.type==='regular')action=n.payload.confirmed?note('Подтверждено: '+money(n.payload.confirmedAmount)):button('Посмотреть сумму и условия','open-regular',`data-notice="${e(n.id)}"`);
    else if(n.type==='purchase')action=link('Все операции','history');
    else if(n.type==='month')action=link('Открыть стол','table');
    else action=link('Посмотреть награды','rewards');
    return `<article class="notice"><p>${e(n.text)}</p>${action}</article>`;
  }).join(''):note('Новых уведомлений пока нет.'));}
  function contents(){const balance=M.cardBalance(s),p=M.projection(s),f=M.forecast(s);switch(view){
    case 'bank':return `<section class="bank-welcome"><span class="eyebrow">Альфа-Онлайн</span><h1>Добрый день, Александр</h1><p>Ваши деньги и планы — под рукой.</p></section><div class="bank-products"><button class="bank-account-tile" data-bank-placeholder="Альфа-Карта">${uiIcon('card')}<span>Альфа-Карта · 0000</span><strong>${e(money(balance))}</strong><small>Дебетовая карта</small></button><button class="bank-account-tile" data-bank-placeholder="Накопления">${uiIcon('target')}<span>Накопления</span><strong>${e(money(s.goals.reduce((n,g)=>n+g.balance,0)))}</strong><small>Ваши цели</small></button></div><section class="bank-game-promo"><div><span class="eyebrow">Больше порядка. Ближе мечта.</span><h2>${BRAND}</h2><p>Разложите покупки по конвертам и превратите небольшую экономию в шаг к большой цели.</p>${button('Открыть игровой стол','open-game','','btn-primary')}</div><div class="promo-cards" aria-hidden="true"><span class="promo-envelope">${uiIcon('envelope')}</span><span class="promo-card">${uiIcon('coffee')}<b>380 ₽</b><small>Кофейня</small></span><span class="promo-seal">${uiIcon('sparkle')}</span></div></section>`;
    case 'home':return card('Расходы — по конвертам. Накопления — к цели.',`<p>Планируйте траты, раскладывайте покупки и откладывайте экономию на важное.</p>${actions(s.onboarded?link('Продолжить мой разбор','table','','btn-primary'):'')}`)+`<div class="entry-grid">${card('Уже есть карта Альфа-Банка',`<p>За пару минут увидите, сколько могло остаться в прошлом месяце.</p>${button('Начать','start-a','','btn-primary')}`)}${card('Новый клиент',`${row('Цель «Квартира»',money(1500000))}${row('Пример срока','февраль 2033')}<p>Сначала игра и ваша цель. Вклад — после первого итога.</p>${button('Оформить карту и попробовать','start-b','','btn-primary')}`)}</div>`+rewardLink();
    case 'savings':return card('Накопления',`<p>Конверты помогают найти экономию и отправить её в вашу цель.</p>${s.onboarded?actions(link('Моя цель','goal')+link('Мой стол','table')):button('Начать','start-a','','btn-primary')}${s.onboarded?s.goals.map(x=>actions(button(`${x.name} · ${money(x.balance)}`,'select-goal',`data-id="${e(x.id)}"`))).join(''):''}`);
    case 'intro':return card('Покажем, сколько могло остаться',`<p>Используем операции вашей карты за последние 30 дней. В короткой партии — 10 крупных и частых покупок. Прогноз предложим по средним тратам за 3 месяца.</p>${note('Пробная партия не влияет на текущий баланс и статистику. Конверты — учёт поверх карты, отдельные счета не открываются.')}${actions(link('Попробовать на моих покупках','trial','','btn-primary')+button('Ввести самому','manual'))}${rewardLink()}`);
    case 'new':return card('Сначала игра и мечта',`${row('Цель «Квартира»',money(g().target))}${row('Срок',month(g().deadline))}<p>Оформите демонстрационную дебетовую карту. Цифровая карта станет доступна сразу; доступность реального продукта — заглушка для согласования.</p>${s.hasCard?actions(link('Попробовать на примерах','training','','btn-primary')+link('Изменить цель','goal-edit')):button('Оформить цифровую карту','issue-card','','btn-primary')}${note('На этом шаге вклад не открывается.')}${rewardLink()}`);
    case 'trial':case 'training':return renderBoard(true);
    case 'trial-result':{const spent=M.trialOperations.filter(o=>(s.trial.assignments[o.id]||o.suggested)!=='reserve').reduce((n,o)=>n+o.amount,0),budget=M.baseEnvelopes.filter(x=>x.id!=='reserve').reduce((n,x)=>n+x.plan,0),economy=Math.max(0,budget-spent);return card('В прошлом месяце могло остаться '+money(economy),`${row('Прогноз повседневных расходов',money(budget))}${row('Повседневные покупки за 30 дней',money(spent))}${note('Расчёт по демонстрационной истории. Сегодняшний доступный остаток карты показан перед переводом.')}${actions(link('Поставить цель и отщипнуть','goal-edit',`data-after="pinch" data-amount="${economy}"`,'btn-primary')+link('Сначала настроить конверты','setup'))}`);}
    case 'setup':return card('Пять конвертов одним подтверждением',M.baseEnvelopes.map(x=>row(x.name,'Условный учёт')).join('')+note('Деньги остаются на карте. Нет отдельных счетов и договоров. Запас и Цель сохраняются всегда; вклад откроется только с отдельным подтверждением.')+actions(link('Подтвердить набор','goal-edit','data-after="forecast"','btn-primary')+button('Есть ребёнок? Добавить Дети','quick-add','data-id="children"')+button('Есть машина? Добавить Автомобиль','quick-add','data-id="car"'))+card('Добавить под свою жизнь',actions(M.extras.map(x=>button(x.name,'quick-add',`data-id="${x.id}" ${s.envelopes.some(en=>en.type===x.id)?'disabled':''}`)).join(''))+link('Пропустить и продолжить','goal-edit','data-after="forecast"')));
    case 'goal-edit':{const editing=ctx.newGoal?{name:'Новая цель',target:1500000,deadline:M.addMonths(s.month,75)}:g(),preview=M.projection(s,ctx.newGoal?{...editing,balance:0,monthly:Math.ceil(editing.target/75)}:editing);return card(ctx.newGoal?'Новая цель':'На что будем копить?',form('goal',field('Название','name',editing.name,'text','required maxlength="80"')+field('Сумма цели, ₽','target',editing.target,'number','required min="1"')+field('Срок цели','deadline',editing.deadline,'month',`required min="${M.addMonths(s.month,1)}"`)+`<div data-goal-preview>${row('Ежемесячный щипок',money(preview.monthly))}${row('Примерный доход по ставке до 9%',money(preview.interest))}</div>`+note('Ежемесячный взнос рассчитывается без процентов. Доход — пример при ежемесячном пополнении и демонстрационной ставке до 9%.')+submit('Сохранить цель'))+(!ctx.newGoal&&!g().opened&&M.canPinch(s)?button('Сохранить цель и открыть вклад','save-goal-open'):'')+button('Открыть вклад позже, сохранить расчёт','save-goal-later'));}
    case 'forecast':if(s.monthClosed)return card('Прогноз месяца сохранён',note('Этот месяц уже закрыт. Для новых сумм используйте прогноз следующего месяца.')+actions(link('Следующий прогноз','next','','btn-primary')+link('Сохранённый итог','summary')));return card('Ваш прогноз на '+month(s.month),note(s.mode==='A'?'Начальные суммы — средние за 3 месяца. Вы можете изменить каждую.':'Начните с обязательного, предусмотрите не меньше 10% в цель и оставьте запас. Пустые поля заполняете вы.')+form('forecast',field('Доход за месяц, ₽','income',s.income??'','number','required min="1"')+`<div class="form-grid">${forecastFields()}</div>`+`<div data-forecast-preview>${row('Конверты',money(f.budget))}${row('Плановый щипок',money(f.goal))}${row('Всего',money(f.total))}${row('Свободные',s.income===null?'—':money(f.free))}</div>`+`<p class="budget-warning" data-budget-warning ${f.deficit&&s.income!==null?'':'hidden'}>Прогноз и щипок больше дохода на ${e(money(f.deficit))}. Можно изменить суммы или сохранить этот ориентир.</p>`+submit('Сохранить прогноз'))+actions(button('Заполнить пример','forecast-example')+link('Изменить сумму и срок цели','goal-edit','data-after="forecast"')));
    case 'salary':{const receipt=s.receipts.find(r=>r.id===ctx.receiptId&&!r.allocated&&r.month===s.month)||s.receipts.find(r=>!r.allocated&&r.month===s.month);if(!receipt)return card('Все поступления распределены',actions(link('Показать аванс или зарплату','income')+link('К столу','table')));const draft=M.suggestDistribution(s,receipt);ctx.receiptId=receipt.id;return card(receipt.label+' · '+money(receipt.amount),note('Деньги поступили на карту. Распределение — только учёт: платить картой можно как обычно. Перевод во вклад подтверждается отдельно.')+form('salary',`<div class="form-grid">${s.envelopes.map(x=>field(x.name,x.id,draft.plans[x.id],'number','required')).join('')}</div>`+field('Запланировать в цель, ₽','reserve',draft.reserve,'number','required')+`<p data-salary-free>Остаток попадёт в Свободные.</p>`+submit('Распределить по прогнозу'))+note('Поддерживаются аванс и зарплата. Уже распределённые суммы не начисляются повторно.')+`<label class="check-row"><input type="checkbox" data-toggle="automaticSalary" ${s.automaticSalary?'checked':''}>Распределять следующие поступления автоматически</label>`);}
    case 'income':return card('Показать поступление на карту',form('income',field('Сумма поступления, ₽','amount',s.receipts.some(r=>r.month===s.month)?60000:120000,'number','required min="1"')+select('Поступление','label',[{id:'Зарплата',name:'Зарплата'},{id:'Аванс',name:'Аванс'},{id:'Другое поступление',name:'Другое поступление'}],'Зарплата')+submit('Показать поступление'))+note('Демонстрационное событие. Настоящие деньги не зачисляются.'));
    case 'payroll':return card('Перенести зарплату на карту',`<p>Когда зарплата и покупки на одной карте, конверты сразу получают данные для бюджета. Выгода и оффер — заглушка GTM.</p>${row('Счёт для зарплаты','40817 000 0 0000 0000000 · пример')}${row('Получатель','Александр · демонстрационные реквизиты')}${actions(button('Скопировать реквизиты','copy-payroll')+button('Я передал реквизиты работодателю','payroll-ready','','btn-primary')+link('Позже','table'))}${s.payrollTransferred?note('Перенос отмечен. В демоверсии можно показать первую зарплату кнопкой ниже.')+link('Показать поступление зарплаты','income'):''}`);
    case 'table':return renderBoard();
    case 'purchase':return card('Новая покупка картой',form('purchase',field('Магазин','name','Кофейня','text','required maxlength="80"')+field('Сумма, ₽','amount',380,'number','required min="0.01"')+select('Категория операции','category',M.categories,'restaurant')+submit('Показать покупку'))+note('Демонстрация обычной операции. Покупка оплачивается один раз; карточка нужна для учёта.'));
    case 'envelope':case 'reserve':case 'unplanned':{const id=view==='reserve'?'reserve':view==='unplanned'?'unplanned':ctx.envelope||'cafe',x=M.totals(s).find(x=>x.id===id)||M.totals(s)[0];ctx.envelope=x.id;const ops=M.currentOps(s).filter(o=>o.envelope===x.id);return card(x.name,row('Прогноз',money(x.plan))+row('Потрачено',money(x.spent))+row('Осталось',money(x.remaining))+note(x.id==='reserve'?'Запас доступен для вынужденных трат. Никаких штрафов и ограничений оплаты картой.':x.id==='unplanned'?'Неожиданные расходы — часть жизни. Эти покупки показаны в итоге без штрафов.':'Конверт — категория учёта. Деньги находятся на карте.')+(M.task(s).kind==='fastfood'&&s.bindings.fastfood===x.id?taskCard(true):'')+(M.canPinch(s)&&M.available(s,x.id)>0&&x.id!=='reserve'?link(`Осталось ${money(x.remaining)}. Отщипнуть во вклад?`,'pinch',`data-source="${x.id}" data-amount="${Math.max(0,x.remaining)}"`,'btn-primary'):'')+transactionList(ops)+actions(link('Изменить прогноз','forecast')+link('К столу','table')));}
    case 'move':{const op=M.currentOps(s).find(o=>o.id===ctx.operationId);return card('Переложить карточку',op?`<p>${e(op.name)} · ${money(op.amount)}</p>${actions(options().map(x=>button(x.name,'move-to',`data-envelope="${e(x.id)}"`)).join(''))}${note('Общая сумма расходов не изменится. Вклад «Цель» не используется для оплаты покупок.')}`:note('Выберите покупку в истории конверта.'));}
    case 'refund':{const op=s.operations.find(o=>o.id===ctx.operationId&&o.amount>0);return card('Возврат покупки',op?form('refund',`<p>${e(op.name)} · ${money(op.amount)}</p>`+field('Сумма возврата, ₽','amount',M.refundable(s,op),'number','required min="0.01"')+submit('Показать возврат отдельной карточкой'))+note('Возврат уменьшает расходы исходного конверта и не считается новым доходом.'):note('Выберите покупку через историю конверта.'));}
    case 'history':return historyPage();
    case 'archive':return archivePage();
    case 'notifications':return notificationsPage();
    case 'rules':return rulesPage();
    case 'rule':{const op=s.operations.find(o=>o.id===ctx.operationId);return card('Всегда сюда',op?form('rule',field('Магазин','merchant',op.name,'text','required')+select('Конверт','envelope',options(),op.envelope||M.suggested(s,op))+`<label class="check-row"><input type="checkbox" name="enabled" ${s.rules[op.name.toLocaleLowerCase('ru')]?'checked':''}>Следующие покупки магазина раскладывать автоматически</label>`+submit('Сохранить правило'))+note('Закреплённые покупки не попадают в руку. Правило можно выключить в любое время.'):link('Открыть правила','rules'));}
    case 'tasks':return taskCard()+link('К столу','table');
    case 'goal':return goalPage();
    case 'pinch':return pinchPage();
    case 'deposit':return card('Открыть пополняемый вклад «Цель»',`${row('Цель',g().name)}${terms()}${ctx.openOnly?button('Подтвердить открытие вклада','open-deposit','','btn-primary'):row('Первый щипок',money(ctx.amount))+link('Проверить сумму и подтвердить','confirm','','btn-primary')}${actions(link('Открыть позже','goal'))}`);
    case 'confirm':return card('Подтвердите щипок',`${row('Откуда',ctx.source==='planned'?'Запланировано в цель':ctx.source==='card'?'Альфа-Карта':ctx.source==='leftovers'?'Остатки бюджетных конвертов без Запаса':envelopeName(ctx.source))}${row('Куда','Вклад · '+g().name)}${row('Сумма',money(ctx.amount))}${row('Останется на карте',money(balance-Number(ctx.amount)))}${!g().opened?note('Вклад ещё не открыт. Подтверждение откроет его и переведёт только указанную сумму.'):''}${terms()}${rewardLink()}${actions(button(g().opened?'Подтвердить перевод':'Подтвердить открытие и перевод','confirm-transfer','','btn-primary')+button('Изменить сумму','edit-transfer'))}`);
    case 'result':return card(s.lastResult?.kind==='withdraw'?'Деньги снова на карте':'Цель стала ближе',`${row('Сумма',money(s.lastResult?.amount))}${row('В цели',money(g().balance))}${row('На карте',money(balance))}${row('До операции',date(s.lastResult?.beforeDate))}${row('Новая оценка даты',date(s.lastResult?.afterDate))}<p>Ориентировочная дата цели ${s.lastResult?.kind==='withdraw'?'отодвинулась':'приблизилась'} на ${s.lastResult?.days||0} дн. при дальнейшем взносе ${money(g().monthly)} в месяц, без учёта процентов.</p>${actions(link('Посмотреть цель','goal')+link('Моя награда','rewards')+link('К столу','table')+(!s.onboarded?link('Настроить конверты','setup'):''))}`);
    case 'withdraw':return card('Если деньги понадобились',row('Во вкладе',money(g().balance))+terms()+form('withdraw',field('Снять на карту, ₽','amount',Math.min(3200,g().balance),'number','required min="0.01"')+`<p data-withdraw-preview>При снятии цель станет дальше. В демонстрации доход к выплате по снимаемой сумме пересчитывается до 0 ₽.</p>`+submit('Подтвердить досрочное снятие'))+link('Оставить деньги в цели','goal'));
    case 'regular':return card('Регулярный щипок',note('В конце месяца придёт уведомление с суммой. Без отдельного подтверждения деньги не переводятся. Запас не включается в правило остатков.')+form('regular',select('Цель','goalId',s.goals,s.regular.goalId||g().id)+select('Правило','kind',[{id:'leftovers',name:'В конце месяца: остатки бюджетных конвертов'},{id:'fixed',name:'В конце месяца: фиксированная сумма'}],s.regular.kind)+`<div data-regular-fixed ${s.regular.kind==='fixed'?'':'hidden'}>${field('Фиксированная сумма, ₽','amount',s.regular.amount,'number',`required min="0.01" ${s.regular.kind==='fixed'?'':'disabled'}`)}</div>`+`<label class="check-row"><input type="checkbox" name="enabled" ${s.regular.enabled?'checked':''}>Правило включено</label>`+submit('Сохранить правило'))+button(s.regular.enabled?'Выключить одним касанием':'Включить одним касанием','toggle-regular')+link('К цели','goal'));
    case 'milestones':return card('Этапы вашей цели',`<p>${e(g().name)} · ${money(g().balance)} из ${money(g().target)}</p>${[25,50,75,100].map(percent=>`<article class="milestone"><h3>${percent}% · ${money(g().target*percent/100)}</h3><p>${g().balance>=g().target*percent/100?'Этап достигнут.':'Предложение появится при достижении этапа.'}</p><div class="partner-placeholder">Место для предложения партнёра. Партнёр и условия — заглушки.</div></article>`).join('')}${link('Вернуться к цели','goal')}`);
    case 'summary':return summaryPage();
    case 'next':return card('Прогноз на '+month(M.addMonths(s.month,1)),note('Копия текущего прогноза с поправкой по фактическим тратам. Обязательные и чувствительные категории автоматически не уменьшаются.')+form('next',`<div class="form-grid">${forecastFields(M.nextProposal(s))}</div>`+row('Плановый щипок',money(g().monthly))+submit('Принять прогноз и начать месяц')));
    case 'rewards':return rewardsPage();
    case 'reward-terms':return card('Условия наград — до начала действия',`<p>Все награды демонстрационные. Размеры, сроки, лимиты и конкретные акции ещё не утверждены.</p>${row('Разбор дней','Бонусы · размер — заглушка')}${row('Сошедшийся прогноз','Кэшбэк · размер — заглушка')}${row('Выполненное задание','Бонусы / участие в акции · условия — заглушки')}${row('Подтверждённый щипок','Кэшбэк / участие в акции · условия — заглушки')}${note('Задание можно отложить или заменить без потери других наград. Вынужденные и чувствительные траты не штрафуются. В прототипе допуск совпадения — 5% или 100 ₽; финальные правила согласуются.')}${actions(link('К заданиям','tasks')+link('К наградам','rewards')+link('К столу','table'))}`);
    case 'settings':return settingsPage();
    case 'help':return card('Как играть в «'+BRAND+'»',`<p>Прогноз → покупки в руке → разбор по конвертам → экономия → подтверждённый щипок → награда → следующий месяц.</p>${note('Конверты — учёт поверх карты: они не мешают платить. Вклад — отдельный продукт с условиями. Покупка уже оплачена, перенос карточки не списывает её повторно.')}${actions(link('Мой стол','table')+link('Две точки входа','home')+link('Условия наград','reward-terms'))}`);
    default:return card('Продолжим с вашего стола',link('Открыть стол','table'));
  }}
  function rulesPage(){return card('Подсказки категорий и правила магазинов',form('bindings',M.categories.map(c=>select(c.name,c.id,options(),s.bindings[c.id])).join('')+submit('Сохранить привязки'))+`<h3>Всегда сюда</h3>`+(Object.keys(s.rules).length?Object.entries(s.rules).map(([merchant,target])=>row(merchant,envelopeName(target))+button('Выключить правило','remove-rule',`data-merchant="${e(merchant)}"`)).join(''):note('Правило можно создать у любой карточки или покупки в истории.'))+link('К столу','table'));}
  function settingsPage(){if(s.monthClosed)return card('Набор месяца сохранён',s.envelopes.map(x=>row(x.name,'Конверт сохранён')).join('')+note('Изменить названия и состав можно после перехода к следующему месяцу. Цели и накопления останутся.')+actions(link('Следующий месяц','next','','btn-primary')+link('Мои цели','goal')+link('К столу','table')));const extra=M.extras.find(x=>x.id===ctx.extra)||{id:'custom',name:'Новый конверт'};return card('Ваши конверты',s.envelopes.map(x=>x.protected?row(x.name,'Остаётся всегда'):form('rename',field('Название','name',x.name,'text','required maxlength="80"')+`<input type="hidden" name="id" value="${e(x.id)}">`+actions(submit('Сохранить название')+button('Удалить конверт','delete-envelope',`data-id="${e(x.id)}"`)))).join('')+row('Цель','Остаётся всегда')+card('Добавить под свою жизнь',actions(M.extras.map(x=>button(x.name,'quick-add',`data-id="${x.id}" ${s.envelopes.some(en=>en.type===x.id)?'disabled':''}`)).join(''))+form('add-envelope',select('Тип конверта','type',[{id:'custom',name:'Свой конверт'},...M.extras],extra.id)+field('Название','name',extra.name,'text','required maxlength="80"')+field('Прогноз, ₽','plan',5000,'number','required')+submit('Добавить конверт'))+note('Нужную сумму выделим из Свободных. Чувствительные категории не используются в заданиях на сокращение трат.'))+actions(link('Привязки категорий и магазинов','rules')+link('Добавить новую цель','goal-edit','data-new-goal="true" data-after="goal"')+link(s.onboarded?'К столу':'Продолжить настройку',s.onboarded?'table':'goal-edit','data-after="forecast"')));
  }
  function goalPage(){const p=M.projection(s);return (M.task(s).kind==='pinch'?taskCard(true):'')+card(g().name,`${row('Накоплено',money(g().balance)+' из '+money(g().target))}<div class="progress" role="progressbar" aria-label="Прогресс цели" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${p.progress}"><span style="--progress:${p.progress}%"></span></div>${row('Ежемесячный щипок',money(g().monthly))}${row('Срок цели',month(g().deadline))}${row('При текущем взносе цель ожидается',date(p.estimatedDate))}${row('Оценка дохода по демонстрационной ставке',money(p.interest))}${milestoneHint()}${note(g().opened?'Пополняемый вклад открыт в демонстрации.':'Цель сохранена. Вклад ещё не открыт; деньги остаются на карте.')}${g().balance>=g().target?card('Цель достигнута',`<p>Можно использовать деньги для покупки или первого взноса по ипотеке. Предложение банка и партнёра — заглушка.</p>${link('Использовать накопления','withdraw')}${link('Создать новую цель','goal-edit','data-new-goal="true" data-after="goal"')}`):''}${actions((M.canPinch(s)?link('Отщипнуть во вклад','pinch','data-source="card"'):note('Первый щипок предложим после первого итога месяца.'))+link('Изменить цель','goal-edit','data-after="goal"')+link('Регулярный щипок','regular')+link('Этапы 25 / 50 / 75 / 100%','milestones')+(g().opened?link('Условия и досрочное снятие','withdraw'):'')+link('Добавить новую цель','goal-edit','data-new-goal="true" data-after="goal"'))}${s.goals.length>1?actions(s.goals.map(x=>button(x.name,'select-goal',`data-id="${e(x.id)}"`)).join('')):''}${rewardLink()}`);}
  function pinchPage(){if(!M.canPinch(s))return card('Первый щипок — после первого итога',note('Сейчас изучите остатки и разберите первую покупку. Вклад пока не открывается.')+link('К столу','table'));
    let proposal=null;if(ctx.regularNotice){try{proposal=M.regularProposal(s,ctx.regularNotice);}catch(error){return card('Регулярный щипок',note(error.message)+link('К уведомлениям','notifications'));}if(proposal.goalId!==g().id)return card('Щипок для другой цели',note('Предложение сохранено для той цели, которую вы выбрали при настройке.')+button('Вернуться к предложению','open-regular',`data-notice="${e(ctx.regularNotice)}"`));}
    const sources=proposal?[{id:proposal.source,name:proposal.source==='leftovers'?'Остатки бюджетных конвертов без Запаса':'С карты'}]:[...(ctx.source==='leftovers'?[{id:'leftovers',name:'Остатки бюджетных конвертов без Запаса'}]:[]),{id:'card',name:'С карты'},{id:'planned',name:'Запланировано в цель'},...M.totals(s).filter(x=>!['unplanned','reserve'].includes(x.id)).map(x=>({id:x.id,name:x.name+' · доступно '+money(M.available(s,x.id))}))];
    if(!sources.some(x=>x.id===ctx.source))ctx.source='card';const available=M.available(s,ctx.source),draft=Number(ctx.amount)>0?Number(ctx.amount):Math.min(3200,available);
    return card('Отщипнуть в цель',(proposal?note('Это предложение регулярного щипка. Измените сумму при необходимости. После подтверждения уведомление будет отмечено исполненным.'):'' )+form('pinch',select('Откуда','source',sources,ctx.source)+field('Сумма, ₽','amount',draft,'number','required min="0.01"')+`<p data-pinch-available>Доступно: ${money(available)}. На карте ${money(M.cardBalance(s))}.</p>`+terms()+rewardLink()+submit('Продолжить'))+note('Щипок добровольный. Проверьте, что денег хватит на ближайшие расходы.'));
  }
  function summaryPage(){const r=M.report(s);return card('Ваш '+month(s.month),`${s.monthClosed?note('Месяц закрыт. Итог сохранится при переходе к следующему месяцу.'):note('Это предварительный итог. При закрытии проверим, что все карточки разобраны.')}<div class="report-table-wrap"><table class="report-table"><thead><tr><th>Конверт</th><th>Исходный</th><th>Прогноз</th><th>Факт</th><th>Результат</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${e(x.name)}</td><td>${money(x.original)}</td><td>${money(x.plan)}</td><td>${money(x.actual)}</td><td>${x.matched?'Сошлось':x.difference>=0?'Меньше прогноза':'Можно уточнить прогноз'}</td></tr>`).join('')}<tr><td>Вне плана</td><td>—</td><td>—</td><td>${money(r.unplanned)}</td><td>Без штрафов</td></tr><tr><td>Свободные</td><td>—</td><td>Не распределено</td><td>${money(r.freeSpent)}</td><td>Покупки учтены</td></tr>${r.unassigned?`<tr><td>Ещё не разложено</td><td>—</td><td>—</td><td>${money(r.unassigned)}</td><td>Разберите руку перед закрытием</td></tr>`:''}</tbody></table></div>${row('За месяц',r.matched?'Сошлось в пределах демонстрационного допуска 5%':'Есть разница с прогнозом — это повод скорректировать следующий план')}${row('Прогноз / факт за месяц',money(r.planned)+' / '+money(r.actual))}${row('Экономия без Запаса',money(r.savings))}${row('Отщипнуто во вклад',money(r.pinched))}${!r.matched&&r.largest?note('Больше всего на разницу повлиял конверт «'+r.largest.name+'»: '+money(Math.abs(r.largest.difference))+'.'):''}${actions((s.monthClosed?link('Прогноз следующего месяца','next','','btn-primary'):button('Закрыть месяц','close-month','','btn-primary'))+(s.monthClosed?link('Отщипнуть экономию','pinch','data-source="card"'):'')+link('Награды','rewards'))}${s.archives.length?card('Предыдущие месяцы',s.archives.map(a=>`<div class="archive-row">${row(month(a.month),'Расходы '+money(a.actual)+' · во вклад '+money(a.pinched))}${link('Открыть итог','archive',`data-month="${e(a.month)}"`)}</div>`).join('')):''}`);}
  function rewardsPage(){const r=M.report(s),earned=[s.dayRewards.length>0,s.monthClosed&&r.matched||s.archives.some(a=>a.matched),M.taskComplete(s)||s.completedTasks.length>0||s.archives.some(a=>a.taskCompleted),s.transfers.length>0],labels=['Разбор дней · бонусы','Сошедшийся прогноз · кэшбэк','Выполненное задание · бонусы / участие в акции','Щипок во вклад · кэшбэк / участие в акции'];return card('Награды за ваши действия',labels.map((label,i)=>row(label,earned[i]?'Условие выполнено · размер награды — заглушка':'Условие пока не выполнено')).join('')+note('Размеры, сроки и партнёры появятся после согласования. Отложенные задания и вынужденные траты не отменяют другие награды.')+actions(rewardLink()+link('К столу','table')+(s.monthClosed?link('Следующий месяц','next'):'')));}
  const headings={bank:'Мой банк',home:BRAND,savings:'Накопления',intro:'Знакомьтесь: '+BRAND,new:'Начните с цели',trial:'Пробная партия',training:'Пробуем на примерах',setup:'Ваши конверты',forecast:'Прогноз месяца',table:'Игровой стол',tasks:'Задания',goal:'Ваша цель',summary:'Итог месяца',settings:'Настройки',history:'Все операции',archive:'Сохранённый итог',notifications:'Уведомления'};
  function render(){
    if(!main)return;
    document.body.dataset.view=view;
    main.innerHTML=`${view==='bank'?'':`<div class="game-brand"><span class="game-brand-icon">${uiIcon('envelope')}</span><span><strong>${BRAND}</strong><small>Покупки в порядке. Мечта ближе.</small></span></div><div class="prototype-toolbar">${link('Об игре','home','','btn-quiet')}${link('Уведомления · '+s.notifications.filter(n=>!n.read).length,'notifications','','btn-quiet')}${rewardLink()}</div><header class="page-heading"><div><span class="eyebrow">${e(month(s.month))}</span><h1>${e(headings[view]||BRAND)}</h1></div><span class="player-status">${s.mode==='A'?'Мой бюджет':'Начало пути'}</span></header>${!['home','intro','new','trial','training','setup'].includes(view)?nav():''}`}${contents()}`;
    const sidebar=$('.sidebar');if(sidebar)sidebar.innerHTML=`<section class="bank-summary"><span class="eyebrow">Мои продукты</span><h2>Общий баланс</h2><strong>${e(money(M.cardBalance(s)+s.goals.reduce((n,g)=>n+g.balance,0)))}</strong><div class="bank-product-list"><button data-bank-placeholder="Карты">${uiIcon('card')}<span>Карты<small>Альфа-Карта · 0000</small></span></button><button data-bank-placeholder="Накопления">${uiIcon('target')}<span>Накопления<small>Вклады и счета</small></span></button><button data-bank-placeholder="Настройки банка">${uiIcon('grid')}<span>Настройки<small>Личные данные</small></span></button></div></section><div class="bank-security">${uiIcon('shield')}<p>Демонстрационный прототип.<br>Деньги не списываются.</p></div>`;
    $$('.prototype-footer a').forEach(a=>{a.href='#help';a.dataset.view='help';});
    document.title=(headings[view]||g().name)+' · '+BRAND;
    save();document.dispatchEvent(new Event('envelopes:render'));
  }
  function readForm(f){return Object.fromEntries(new FormData(f).entries());}
  document.addEventListener('submit',event=>{
    const target=event.target.closest('[data-form]');if(!target)return;event.preventDefault();if(!target.reportValidity())return;
    const data=readForm(target),kind=target.dataset.form;
    try{
      if(kind==='history-filters'){ctx.historyMonth=data.period;ctx.historyEnvelope=data.envelope;ctx.historyQuery=data.query;save();render();}
      else if(kind==='goal'){M.setGoal(s,data,Boolean(ctx.newGoal));ctx.newGoal=false;const next=ctx.after==='pinch'?'pinch':ctx.after==='goal'?'goal':'forecast';if(next==='pinch'){ctx.source='card';ctx.amount=ctx.amount||3200;ctx.regularNotice=null;}ctx.after=null;save();go(next);}
      else if(kind==='forecast'){const was=s.onboarded;M.setForecast(s,data.income,data);save();go(was?'table':s.mode==='B'?'payroll':'salary');}
      else if(kind==='salary'){M.distribute(s,ctx.receiptId,{plans:data,reserve:data.reserve});if(s.mode==='A'&&!s.operations.length)seedPurchases();save();go('table');announce('Поступление распределено. Перевод во вклад требует отдельного подтверждения.');}
      else if(kind==='income'){const receipt=M.receiveIncome(s,data.amount,data.label);save();go(receipt.allocated?'table':'salary',{receiptId:receipt.id});announce('Деньги поступили на карту. Уведомление добавлено.');}
      else if(kind==='purchase'){const op=M.createPurchase(s,data);M.markDay(s);save();go('table');announce(op.envelope?'Покупка учтена автоматически по правилу магазина.':'Появилась новая карточка покупки и уведомление.');}
      else if(kind==='refund'){M.refund(s,ctx.operationId,data.amount);save();go('table');announce('Возврат пришёл отдельной карточкой.');}
      else if(kind==='rule'){M.setRule(s,data.merchant,data.envelope,data.enabled==='on');save();go('rules');}
      else if(kind==='bindings'){Object.keys(data).forEach(k=>{if(!M.validEnvelope(s,data[k]))throw Error('Выберите существующий конверт.');});s.bindings={...s.bindings,...data};save();go('rules');}
      else if(kind==='rename'){M.renameEnvelope(s,data.id,data.name);save();render();announce('Название сохранено на столе и в истории.');}
      else if(kind==='add-envelope'){M.addEnvelope(s,data);save();ctx.extra=null;render();announce('Конверт добавлен на стол.');}
      else if(kind==='pinch'){const n=Number(data.amount);if(!(n>0)||n>M.available(s,data.source))throw Error('Сумма больше доступного остатка выбранного источника.');ctx.source=data.source;ctx.amount=n;ctx.openOnly=false;ctx.transferGoalId=g().id;ctx.transferToken='pinch-'+Date.now()+'-'+Math.random().toString(36).slice(2);save();go(g().opened?'confirm':'deposit');}
      else if(kind==='withdraw'){M.withdraw(s,data.amount);save();go('result');}
      else if(kind==='regular'){if(data.kind==='fixed'&&(!(Number(data.amount)>0)||!Number.isFinite(Number(data.amount))))throw Error('Укажите фиксированную сумму больше нуля.');if(!s.goals.some(g=>g.id===data.goalId))throw Error('Выберите цель для регулярного щипка.');s.regular={enabled:data.enabled==='on',kind:data.kind,amount:data.kind==='fixed'?Number(data.amount):s.regular.amount,goalId:data.goalId};save();render();announce('Правило сохранено. Каждый перевод нужно подтвердить отдельно.');}
      else if(kind==='next'){M.nextMonth(s,data);save();go('table');}
    }catch(error){showError(error.message);}
  });
  document.addEventListener('click',event=>{
    const placeholder=event.target.closest('[data-bank-placeholder]');if(placeholder){event.preventDefault();bankStub(placeholder.dataset.bankPlaceholder);return;}
    const control=event.target.closest('[data-action], [data-view]');if(!control)return;
    if(control.dataset.action==='focus-hand'){event.preventDefault();$('#purchase-hand')?.scrollIntoView({behavior:'smooth',block:'start'});$('#purchase-hand')?.focus({preventScroll:true});return;}
    if(control.dataset.view){
      event.preventDefault();const ds=control.dataset,next={};
      if(ds.id){if(ds.view==='move'||ds.view==='refund')next.operationId=ds.id;else next.envelope=ds.id;}
      if(ds.extra)next.extra=ds.extra;if(ds.after)next.after=ds.after;
      if(ds.newGoal)next.newGoal=true;else if(ds.view==='goal-edit')next.newGoal=false;
      if(ds.source)next.source=ds.source;if(ds.amount!==undefined)next.amount=Number(ds.amount);
      if(ds.receipt)next.receiptId=ds.receipt;if(ds.openOnly)next.openOnly=true;
      if(ds.month)next.archiveMonth=ds.month;
      if(ds.view==='history'){next.historyMonth=ds.period||s.month;next.historyEnvelope='all';next.historyQuery='';}
      if(ds.view==='pinch'){next.regularNotice=null;next.transferGoalId=null;next.transferToken=null;}
      if(ds.view==='notifications')s.notifications.forEach(n=>n.read=true);
      go(ds.view,next);return;
    }
    event.preventDefault();const a=control.dataset.action;
    mutate(()=>{
      if(a==='open-game'){prepareTable();go('table');}
      else if(a==='start-a'||a==='start-b'){s=M.create(a==='start-a'?'A':'B');ctx={envelope:'cafe',source:'card',amount:3200};go(a==='start-a'?'intro':'new');}
      else if(a==='quick-add'){const extra=M.extras.find(x=>x.id===control.dataset.id);if(!extra)throw Error('Выберите конверт.');if(s.envelopes.some(x=>x.type===extra.id))throw Error('Этот конверт уже добавлен.');M.addEnvelope(s,{name:extra.name,type:extra.id,plan:5000});announce('Конверт «'+extra.name+'» добавлен. Прогноз можно изменить.');}
      else if(a==='save-goal-open'){const f=$('[data-form="goal"]');if(!f.reportValidity())return;M.setGoal(s,readForm(f),Boolean(ctx.newGoal));ctx.newGoal=false;ctx.openOnly=true;go('deposit');}
      else if(a==='save-goal-later'){const f=$('[data-form="goal"]');if(!f.reportValidity())return;M.setGoal(s,readForm(f),Boolean(ctx.newGoal));ctx.newGoal=false;ctx.after=null;go(s.onboarded?'goal':'forecast');announce('Цель и расчёт сохранены. Вклад можно открыть позже.');}
      else if(a==='manual'){s.envelopes.forEach(x=>x.plan=null);s.income=null;go('setup');}
      else if(a==='issue-card'){s.hasCard=true;go('training');announce('Демонстрационная цифровая карта готова.');}
      else if(a==='forecast-example'){s.income=120000;s.envelopes.forEach(x=>x.plan=M.baseEnvelopes.find(b=>b.id===x.id)?.plan||5000);}
      else if(a==='extra'){ctx.extra=control.dataset.id;}
      else if(a==='delete-envelope'){ctx.deleting=control.dataset.id;const d=$('#demo-message');$('#message-title').textContent='Удалить конверт «'+envelopeName(ctx.deleting)+'»?';$('[data-message-content]').textContent='Покупки останутся в истории и попадут во Вне плана. Неиспользованная сумма вернётся в Свободные.';const old=$('[data-confirm-delete]',d);old?.remove();const b=document.createElement('button');b.className='btn btn-primary';b.dataset.action='confirm-delete';b.dataset.confirmDelete='';b.textContent='Удалить конверт';d.append(b);d.showModal();}
      else if(a==='confirm-delete'){M.deleteEnvelope(s,ctx.deleting);$('#demo-message').close();ctx.deleting=null;}
      else if(a==='rule-edit'){go('rule',{operationId:control.dataset.id});}
      else if(a==='remove-rule'){delete s.rules[control.dataset.merchant];}
      else if(a==='payroll-ready'){s.payrollTransferred=true;if(!s.completedTasks.includes('payroll'))s.completedTasks.push('payroll');go('payroll');announce('Перенос зарплаты отмечен. Дальнейшее поступление покажем отдельно.');}
      else if(a==='copy-payroll'){const text='Демонстрационные реквизиты: 40817 000 0 0000 0000000';if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(text).catch(()=>{});announce('Демонстрационные реквизиты подготовлены для передачи работодателю.');}
      else if(a==='next-day'){s.day=Math.min(28,s.day+1);announce('Наступил следующий демонстрационный день.');}
      else if(a==='seed'){seedPurchases();M.markDay(s);announce('Новые покупки появились в руке, уведомления добавлены.');}
      else if(a==='task-accept'||a==='task-defer'||a==='task-replace'){M.taskAction(s,a==='task-accept'?'accept':a==='task-defer'?'defer':'replace');}
      else if(a==='move-to'){M.assign(s,ctx.operationId,control.dataset.envelope);go('envelope',{envelope:control.dataset.envelope});}
      else if(a==='edit-transfer'){go('pinch');}
      else if(a==='open-regular'){const p=M.regularProposal(s,control.dataset.notice);s.activeGoal=p.goalId;go('pinch',{regularNotice:p.notice.id,source:p.source,amount:p.amount,transferGoalId:p.goalId,transferToken:null});}
      else if(a==='confirm-transfer'){if(ctx.transferGoalId&&ctx.transferGoalId!==g().id)throw Error('Цель изменилась. Проверьте щипок ещё раз.');if(ctx.regularNotice)M.confirmRegular(s,ctx.regularNotice,ctx.amount,ctx.source,!g().opened);else M.transfer(s,ctx.amount,ctx.source,!g().opened,ctx.transferToken);go('result');}
      else if(a==='open-deposit'){M.openDeposit(s);ctx.openOnly=false;go('goal');}
      else if(a==='toggle-regular'){s.regular.enabled=!s.regular.enabled;}
      else if(a==='close-month'){M.closeMonth(s);announce('Месяц закрыт. Можно подтвердить щипок и принять следующий прогноз.');}
      else if(a==='select-goal'){if(!s.goals.some(g=>g.id===control.dataset.id))throw Error('Цель не найдена.');s.activeGoal=control.dataset.id;go('goal');}
      else if(a==='sort-all'){const d=boardData();d.operations.forEach(o=>place(o.id,o.suggested||M.suggested(s,o),false));announce('Все оставшиеся карточки разложены по подсказкам.');}
      else if(a==='practice-reset'){s[view].assignments={};}
      else if(a==='undo'){const h=s.assignmentHistory?.pop();if(h){const o=M.currentOps(s).find(x=>x.id===h.id);if(o)o.envelope=h.previous&&M.validEnvelope(s,h.previous)?h.previous:null;}}
    });
  });
  document.addEventListener('change',event=>{if(event.target.dataset.toggle==='automaticSalary'){s.automaticSalary=event.target.checked;save();announce(s.automaticSalary?'Автоматическая раздача включена. Щипок всё равно подтверждается отдельно.':'Автоматическая раздача выключена.');}});
  document.addEventListener('input',event=>{
    const f=event.target.closest('form');if(!f)return;
    const d=readForm(f);
    if(f.dataset.form==='regular'){const fixed=d.kind==='fixed',box=$('[data-regular-fixed]',f);box.hidden=!fixed;$('[name="amount"]',box).disabled=!fixed;}
    if(f.dataset.form==='goal'){try{const copy=M.clone(s);M.setGoal(copy,d,Boolean(ctx.newGoal));const p=M.projection(copy);$('[data-goal-preview]',f).innerHTML=row('Ежемесячный щипок',money(p.monthly))+row('Примерный доход по ставке до 9%',money(p.interest));}catch{}}
    if(f.dataset.form==='forecast'){const budget=s.envelopes.reduce((n,x)=>n+(Number(d[x.id])||0),0),total=budget+g().monthly,free=(Number(d.income)||0)-total;$('[data-forecast-preview]',f).innerHTML=row('Конверты',money(budget))+row('Плановый щипок',money(g().monthly))+row('Всего',money(total))+row('Свободные',d.income===''?'—':money(free));const warning=$('[data-budget-warning]',f);warning.hidden=free>=0||d.income==='';warning.textContent=`Прогноз и щипок больше дохода на ${money(-free)}. Можно изменить суммы или сохранить этот ориентир.`;}
    if(f.dataset.form==='salary'){const receipt=s.receipts.find(x=>x.id===ctx.receiptId),free=(receipt?.amount||0)-s.envelopes.reduce((n,x)=>n+(Number(d[x.id])||0),0)-(Number(d.reserve)||0);$('[data-salary-free]',f).textContent=free<0?`Распределено больше поступления на ${money(-free)}.`:`В Свободные: ${money(free)}.`;}
    if(f.dataset.form==='pinch')$('[data-pinch-available]',f).textContent=`Доступно ${money(M.available(s,d.source))}. После перевода на карте ${money(balanceSafe()-Number(d.amount||0))}.`;
    if(f.dataset.form==='withdraw')$('[data-withdraw-preview]',f).textContent=`Цель станет дальше примерно на ${g().monthly?Math.round(Number(d.amount||0)/g().monthly*30.44):0} дн. Проценты к выплате в демонстрации пересчитываются до 0 ₽; оценка утраченного будущего дохода по снимаемой части — ${money(g().balance?M.projection(s).interest*Math.min(1,Number(d.amount||0)/g().balance):0)}.`;
  });
  function balanceSafe(){return M.cardBalance(s);}
  function place(id,destination,paint=true){const d=boardData();if(!d)return false;
    if(d.kind==='table'){const op=M.currentOps(s).find(o=>o.id===id);if(!op)return false;M.assign(s,id,destination);}
    else{if(!d.all.some(o=>o.id===id)||!d.envelopes.some(x=>x.id===destination))return false;s[d.kind].assignments[id]=destination;}
    save();if(paint)render();return true;
  }
  window.EnvelopePrototype={boardData,place,announce,get state(){return s;},get view(){return view;}};
  window.addEventListener('popstate',event=>{view=event.state?.view||location.hash.slice(1)||'bank';ctx={...ctx,...event.state?.ctx};render();});
  $$('[data-close-dialog]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
  render();
})();
